param([switch]$Install)
# Bundles src/ into build/DrawuiExporter.rbxmx (a local Studio plugin).
# -Install also copies it to %LOCALAPPDATA%\Roblox\Plugins. Restart Studio (or reload plugins) afterwards.
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$read = { param($p) [IO.File]::ReadAllText((Join-Path $root $p)) }

$iconFile = Join-Path $root 'assets\icon-asset.txt'
$icon = if (Test-Path $iconFile) { (Get-Content $iconFile -Raw).Trim() } else { '' }

$source = @"
-- Drawui Exporter (generated by studio-plugin/build.ps1 - edit studio-plugin/src instead)
local ICON = "$icon"
local Exporter = (function()
$(& $read 'src\Exporter.luau')
end)()
$(& $read 'src\Plugin.server.luau')
"@
$cdata = $source.Replace(']]>', ']]]]><![CDATA[>')
$xml = @"
<roblox xmlns:xmime="http://www.w3.org/2005/05/xmlmime" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="http://www.roblox.com/roblox.xsd" version="4">
	<Item class="Script" referent="RBX0">
		<Properties>
			<string name="Name">DrawuiExporter</string>
			<token name="RunContext">0</token>
			<ProtectedString name="Source"><![CDATA[$cdata]]></ProtectedString>
		</Properties>
	</Item>
</roblox>
"@
$out = Join-Path $root 'build'
New-Item -ItemType Directory -Force -Path $out | Out-Null
$file = Join-Path $out 'DrawuiExporter.rbxmx'
[IO.File]::WriteAllText($file, $xml, [Text.UTF8Encoding]::new($false))
Write-Output "Built $file"

if ($Install) {
    $plugins = Join-Path $env:LOCALAPPDATA 'Roblox\Plugins'
    New-Item -ItemType Directory -Force -Path $plugins | Out-Null
    Copy-Item $file (Join-Path $plugins 'DrawuiExporter.rbxmx') -Force
    Write-Output "Installed to $plugins"
}
